use super::Recipient;
use super::funded;
use super::drain;
use super::super::FemMaterial;
use super::super::NATIVE_MATERIAL_DIMENSION;
use semio_framework_value::{DslValue, ToValue, RetirementDemand, retained_clone::{RetainedCloneGrant, RetainedCloneProgress, RetainedCloneSource, RetainedCloneRef}, retirement::{RetireOwned}};
use semio_framework_value_snapshot_projection::snapshot_projection::{SnapshotProjection, SnapshotProjectionCursor};
use semio_framework_value::shared_issuance::{SealedShared, SharedIssuer};
use semio_framework_value_native_owned::{native_decoding::NativeDecodeControl, native_decoding::NativeReceive, native_decoding::NativeReceiver};
use semio_framework_value_persistent::{list::persistent::PersistentList, list::persistent::PersistentSplice, list::persistent::PersistentSpliceKind, list::persistent::PersistentSet};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn denied(d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{let g=exact(d);[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
fn physical(p:RetainedCloneProgress,g:RetainedCloneGrant,h:semio_framework_trace::HeapAllocationObservation){assert!(p.fits(g));assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn source(input:DslValue)->RetainedCloneSource<DslValue>{let birth=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(input,(),funded(RetirementDemand{copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),capacity_bytes:birth.capacity_bytes,depth:birth.depth,..Default::default()})).unwrap_or_else(|_|panic!("original Material table input")).0}
fn expected(count:usize,prefix:&str)->serde_json::Value{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let row=&f["accepted"].as_array().unwrap().iter().find(|c|c["dimension"].as_u64()==Some(NATIVE_MATERIAL_DIMENSION as u64)).unwrap()["row"];serde_json::Value::Array((0..count).map(|i|{let mut r=row.clone();r["id"]=format!("material-{i}").into();r["name"]=format!("{prefix}{i}").into();r}).collect())}
fn close_receiver<I,T>(r:&mut T)where T:NativeReceiver<I,PersistentList<FemMaterial>>{r.begin_close();for _ in 0..100000{if r.terminal_is_empty(){return;}let d=r.close_demands(4096).unwrap();for g in denied(d){let(s,h)=observe(||r.close_step(g).unwrap());physical(s.progress(),g,h);assert_eq!(s.progress(),Default::default());}let g=funded(d);let(s,h)=observe(||r.close_step(g).unwrap());physical(s.progress(),g,h);}panic!("native Material table close stalled")}
fn received_table(count:usize)->PersistentList<FemMaterial>{received_table_value(expected(count,"Material α🙂 "))}
fn received_table_value(value:serde_json::Value)->PersistentList<FemMaterial>{let original=source(DslValue::from(&value));let(mut r,_)=<PersistentList<FemMaterial>as NativeReceive<DslValue>>::begin_receive(funded(<PersistentList<FemMaterial>as NativeReceive<DslValue>>::receive_birth_demand())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut recipient=Recipient;while !r.output_ready(){let g=funded(r.demands(original.borrow(),4096).unwrap());assert!(control.with_construction_recipient(&mut recipient,|control|r.advance(original.borrow(),control,4096,g)).unwrap().progress().fits(g));}let g=funded(r.take_demand().unwrap());let(root,_)=r.take(g).unwrap().unwrap();close_receiver::<DslValue,_>(&mut r);drain(original);root}
fn row_source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),funded(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).unwrap_or_else(|_|panic!("actual ranked Material original")).0}
fn sealed_original(row:RetainedCloneRef<'_,FemMaterial>)->SealedShared<FemMaterial>{let(mut cursor,_)=FemMaterial::begin_projection(funded(FemMaterial::projection_birth_demand())).unwrap();while !cursor.ready(){let g=funded(cursor.demands(row,4096).unwrap());let(s,h)=observe(||cursor.advance(row,g).unwrap());physical(s.progress(),g,h);}let g=funded(cursor.take_demand().unwrap());let(value,_)=cursor.take(g).unwrap().unwrap();cursor.begin_close();while !cursor.terminal_is_empty(){let g=funded(cursor.close_demands(4096).unwrap());let(s,h)=observe(||cursor.close_step(g).unwrap());physical(s.progress(),g,h);}let d=semio_framework_value_native_owned::native_decoding::NativeOwnedDecodeControl::shared_birth_demand::<FemMaterial>();SealedShared::admit(value,SharedIssuer::owned(),funded(d)).unwrap_or_else(|_|panic!("actual Material original inverse row birth")).0}
fn splice(original:RetainedCloneRef<'_,PersistentList<FemMaterial>>,authored:Option<RetainedCloneRef<'_,SealedShared<FemMaterial>>>,kind:PersistentSpliceKind,index:usize,cut:Option<usize>)->Option<PersistentList<FemMaterial>>{let mut cursor=PersistentSplice::new(kind,index);let mut turns=0;let mut ready=false;while !ready&&cut.is_none_or(|cut|turns<cut){let d=cursor.demand(original,authored).unwrap();for g in denied(d){let(s,h)=observe(||cursor.advance(original,authored,g).unwrap());physical(s.progress(),g,h);assert_eq!(s.progress(),Default::default());}let g=funded(d);let(s,h)=observe(||cursor.advance(original,authored,g).unwrap());physical(s.progress(),g,h);ready=matches!(s,semio_framework_value::retained_clone::RetainedCloneStep::Complete(_));turns+=1;}let output=if ready{let g=funded(cursor.take_demand());let((value,p),h)=observe(||cursor.take(g).unwrap().unwrap());physical(p,g,h);Some(value)}else{None};cursor.begin_close();while !cursor.terminal_is_empty(){let d=cursor.close_demand(4096).unwrap();for g in denied(d){let(s,h)=observe(||cursor.close_step(g).unwrap());physical(s.progress(),g,h);assert_eq!(s.progress(),Default::default());}let g=funded(d);let(s,h)=observe(||cursor.close_step(g).unwrap());physical(s.progress(),g,h);}let(_,h)=observe(||drop(cursor));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));output}
fn set(original:RetainedCloneRef<'_,PersistentList<FemMaterial>>,authored:RetainedCloneRef<'_,SealedShared<FemMaterial>>,index:usize,cut:Option<usize>)->Option<PersistentList<FemMaterial>>{let mut cursor=PersistentSet::new(index);let mut turns=0;while !cursor.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=cursor.demand(original,authored).unwrap();for g in denied(d){let(s,h)=observe(||cursor.advance(original,authored,g).unwrap());physical(s.progress(),g,h);assert_eq!(s.progress(),Default::default());}let g=funded(d);let(s,h)=observe(||cursor.advance(original,authored,g).unwrap());physical(s.progress(),g,h);turns+=1;}let output=if cursor.output_ready(){let g=funded(PersistentList::<FemMaterial>::projection_demand());let((value,p),h)=observe(||cursor.take(g).unwrap().unwrap());physical(p,g,h);Some(value)}else{None};cursor.begin_close();while !cursor.terminal_is_empty(){let d=cursor.close_demand(4096).unwrap();for g in denied(d){let(s,h)=observe(||cursor.close_step(g).unwrap());physical(s.progress(),g,h);assert_eq!(s.progress(),Default::default());}let g=funded(d);let(s,h)=observe(||cursor.close_step(g).unwrap());physical(s.progress(),g,h);}let(_,h)=observe(||drop(cursor));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));output}
#[test]
fn native_material_ranked_insert_remove_set_and_inverse_preserve_original_rows(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for case in f["structural"].as_array().unwrap(){let count=case["count"].as_u64().unwrap()as usize;let index=case["index"].as_u64().unwrap()as usize;let kind=case["kind"].as_str().unwrap();for cut in std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let original=row_source(received_table(count));let mut authored=expected(1,"Authored α🙂 ");authored[0]["id"]=if kind=="set"{format!("material-{index}")}else{"material-authored".to_owned()}.into();authored[0]["e"]=215000000000_f64.into();let authored_table=row_source(received_table_value(authored));let native=sealed_original(authored_table.borrow().project(0,|table|table.get(0).unwrap()));let native=row_source(native);let output=if kind=="set"{set(original.borrow(),native.borrow(),index,cut)}else{splice(original.borrow(),(kind=="insert").then(||native.borrow()),if kind=="insert"{PersistentSpliceKind::Insert}else{PersistentSpliceKind::Remove},index,cut)};
 if let Some(output)=output{let output=row_source(output);let mut ids:Vec<_>=(0..count).map(|i|format!("material-{i}")).collect();match kind{"insert"=>ids.insert(index,"material-authored".into()),"remove"=>{ids.remove(index);},"set"=>ids[index]=format!("material-{index}"),_=>panic!("declared Material structural kind")};assert_eq!(output.borrow().get().len(),ids.len());for(i,id)in ids.iter().enumerate(){assert_eq!(output.borrow().get().get(i).unwrap().id.as_str(),id);let previous=if kind=="insert"{(i!=index).then(||i-usize::from(i>index))}else if kind=="remove"{Some(i+usize::from(i>=index))}else{(i!=index).then_some(i)};if let Some(previous)=previous{assert!(std::ptr::eq(output.borrow().get().get(i).unwrap(),original.borrow().get().get(previous).unwrap()));}}
  let inverse=if kind=="insert"{splice(output.borrow(),None,PersistentSpliceKind::Remove,index,None).unwrap()}else{let removed=sealed_original(original.borrow().project(index,move|table|table.get(index).unwrap()));let removed=row_source(removed);let result=if kind=="set"{set(output.borrow(),removed.borrow(),index,None).unwrap()}else{splice(output.borrow(),Some(removed.borrow()),PersistentSpliceKind::Insert,index,None).unwrap()};drain(removed);result};assert_eq!(&inverse,original.borrow().get());for i in 0..count{assert!(std::ptr::eq(inverse.get(i).unwrap().id.get(),original.borrow().get().get(i).unwrap().id.get()));assert!(std::ptr::eq(inverse.get(i).unwrap().name.get(),original.borrow().get().get(i).unwrap().name.get()));}drain(inverse);drain(output);
 }assert_eq!(original.borrow().get().len(),count);drain(native);drain(authored_table);drain(original);eprintln!("[DEBUG] actual Material ranked dimension={NATIVE_MATERIAL_DIMENSION} kind={kind} rows={count} index={index} cut={cut:?} originalPointers=true inverseFields=true terminalHeap=0");}}}
#[test]
fn native_material_reorder_preserves_original_field_issuers_and_inverse_order(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for case in f["reorder"].as_array().unwrap(){let count=case["count"].as_u64().unwrap()as usize;let from=case["from"].as_u64().unwrap()as usize;let to=case["to"].as_u64().unwrap()as usize;for cut in std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let original=row_source(received_table(count));let moved=row_source(sealed_original(original.borrow().project(from,move|table|table.get(from).unwrap())));let removed=row_source(splice(original.borrow(),None,PersistentSpliceKind::Remove,from,None).unwrap());if let Some(output)=splice(removed.borrow(),Some(moved.borrow()),PersistentSpliceKind::Insert,to,cut){let output=row_source(output);let mut ranks:Vec<_>=(0..count).collect();let rank=ranks.remove(from);ranks.insert(to,rank);for(i,rank)in ranks.iter().enumerate(){let row=output.borrow().get().get(i).unwrap();let before=original.borrow().get().get(*rank).unwrap();assert_eq!(row.id.as_str(),before.id.as_str());assert!(std::ptr::eq(row.id.get(),before.id.get()));assert!(std::ptr::eq(row.name.get(),before.name.get()));}let inverse_removed=row_source(splice(output.borrow(),None,PersistentSpliceKind::Remove,to,None).unwrap());let inverse=splice(inverse_removed.borrow(),Some(moved.borrow()),PersistentSpliceKind::Insert,from,None).unwrap();assert_eq!(&inverse,original.borrow().get());drain(inverse);drain(inverse_removed);drain(output);}assert_eq!(original.borrow().get().len(),count);drain(removed);drain(moved);drain(original);eprintln!("[DEBUG] actual Material reorder dimension={NATIVE_MATERIAL_DIMENSION} rows={count} from={from} to={to} cut={cut:?} originalFields=true inverseOrder=true terminalHeap=0");}}}
#[test]
fn native_material_table_receives_original_order_and_closes_cancelled_frontiers(){
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for count in f["counts"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;let expected=expected(count,f["prefix"].as_str().unwrap());let cuts:Vec<_>=std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|c|Some(c.as_u64().unwrap()as usize))).collect();for cut in cuts{
  let original=source(DslValue::from(&expected));let foreign=source(DslValue::from(&expected));let pointer=std::ptr::from_ref(original.borrow().get());let d=<PersistentList<FemMaterial>as NativeReceive<DslValue>>::receive_birth_demand();for g in denied(d){let(result,h)=observe(||<PersistentList<FemMaterial>as NativeReceive<DslValue>>::begin_receive(g));assert!(result.is_err());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let g=exact(d);let((mut r,p),h)=observe(||<PersistentList<FemMaterial>as NativeReceive<DslValue>>::begin_receive(g).unwrap());physical(p,g,h);let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut recipient=Recipient;let mut turns=0;
  while !r.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=r.demands(original.borrow(),4096).unwrap();if turns>0{assert!(r.demands(foreign.borrow(),4096).is_err());}for g in denied(d){let(s,h)=observe(||control.with_construction_recipient(&mut recipient,|control|r.advance(original.borrow(),control,4096,g)).unwrap());physical(s.progress(),g,h);assert_eq!(s.progress(),Default::default());assert_eq!(r.demands(original.borrow(),4096).unwrap(),d);}let g=exact(d);let(s,h)=observe(||control.with_construction_recipient(&mut recipient,|control|r.advance(original.borrow(),control,4096,g)).unwrap());physical(s.progress(),g,h);assert_eq!(std::ptr::from_ref(original.borrow().get()),pointer);turns+=1;}
  if cut.is_none(){let d=r.take_demand().unwrap();for g in denied(d){let(out,h)=observe(||r.take(g).unwrap());assert!(out.is_none());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let g=exact(d);let((root,p),h)=observe(||r.take(g).unwrap().unwrap());physical(p,g,h);assert_eq!(root.len(),count);for i in 0..count{let value=root.get(i).unwrap().to_value();assert_eq!(value.get("id").unwrap().as_str(),expected[i]["id"].as_str());assert_eq!(value.get("name").unwrap().as_str(),expected[i]["name"].as_str());for key in ["e","g","nu","rho"]{if let Some(number)=expected[i].get(key){assert_eq!(value.get(key).unwrap().as_f64().unwrap().to_bits(),number.as_f64().unwrap().to_bits());}}drain(value);}drain(root);}
  close_receiver::<DslValue,_>(&mut r);let(_,h)=observe(||drop(r));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));drain(original);drain(foreign);eprintln!("[DEBUG] actual Material table dimension={NATIVE_MATERIAL_DIMENSION} rows={count} cut={cut:?} turns={turns} deniedAxes=5 terminalHeap=0");
 }}
}
